import React, { useRef, useState, useEffect } from "react";
import { ArrowRight, Menu, X, Wallet, User, MapPin, Check, Quote, GraduationCap, Globe, HelpCircle, DollarSign, ShieldCheck, ClipboardList, Users, FileText, Mail, Plane, MessageCircle, School, Building2, BadgeCheck, Search, Heart, ChevronDown, ChevronLeft, ChevronRight, Target, BookOpen, Award, Coffee, Phone, Instagram, Facebook, Linkedin, Youtube, Twitter, Share2, Link, Clock, Search as SearchIcon, Trophy, Plane as PlaneIcon, Heart as HeartIcon, Briefcase, Star as LucideStar, Send, Calendar, Loader2, Play, Zap } from "lucide-react";

/* ------------------------------------------------------------------ */
/*  EasyIntake — Full Landing Page  (v4 — ZERO external dependencies)  */
/*                                                                     */
/*  The artifact sandbox blocks external <script> loading, so GSAP     */
/*  never ran. Every animation is now native and guaranteed:           */
/*   • Entrance choreography  → CSS keyframes with per-element delays  */
/*   • Sticker hover physics  → JS transforms + springy cubic-beziers  */
/*   • Scroll reveals         → IntersectionObserver                   */
/*   • Pinned "How It Works"  → position:sticky + rAF scrub engine     */
/*                                                                     */
/*  Brand: Orange #F05A28 · Ink #222222 · Cream #FBF8F2 · Navy #0D1F3D */
/* ------------------------------------------------------------------ */

