/* -------------------- Sticker hover physics (no libs) --------------------- */
/* Springy paper feel: transform + overshooting cubic-bezier transitions.    */

const rand = (min, max) => min + Math.random() * (max - min);

function stickerEnter(e) {
  const el = e.currentTarget;
  const base = parseFloat(el.dataset.rot || 0);
  el.style.transition = "transform .3s cubic-bezier(.2,.8,.3,1.4)";
  el.style.transform = `translate(${rand(-8, 8)}px, ${rand(-8, 8)}px) rotate(${base + rand(-6, 6)}deg) scale(1.08)`;
}
function stickerLeave(e) {
  const el = e.currentTarget;
  const base = parseFloat(el.dataset.rot || 0);
  el.style.transition = "transform .65s cubic-bezier(.34,1.8,.4,1)";
  el.style.transform = `rotate(${base}deg)`;
}

/* --------------------------- Components ---------------------------- */
/* Three layers, three jobs — no conflicting transforms:
   1. .ei-sticker-pos + .ei-a-pop  → entrance pop (CSS keyframe)
   2. .ei-float                    → ambient paper drift (CSS infinite)
   3. .ei-cutout / .ei-badge       → hover physics (JS transform)      */

const CutoutSticker = ({ rot = 0, pos, width, alt, src, z = 10, side = true, mobileOnly = false, d = "1s", fd = "3.4s", fx = "4px", fy = "-10px" }) => (
  <div
    className={`ei-sticker-pos ei-pre ei-a-pop ${side ? "ei-side" : ""} ${mobileOnly ? "ei-mobile-badge" : ""}`}
    style={{ ...pos, zIndex: z, "--d": d }}
  >
    <div className="ei-float" style={{ "--fd": fd, "--fx": fx, "--fy": fy }}>
      <div
        className="ei-cutout"
        data-rot={rot}
        onMouseEnter={stickerEnter}
        onMouseLeave={stickerLeave}
        style={{ width, transform: `rotate(${rot}deg)` }}
      >
        <img src={src} alt={alt} draggable="false" />
      </div>
    </div>
  </div>
);

const BadgeSticker = ({ rot = 0, pos, label, dark = false, side = true, mobileOnly = false, z = 30, d = "1.3s", fd = "3.8s", fx = "-4px", fy = "-8px" }) => (
  <div
    className={`ei-sticker-pos ei-pre ei-a-pop ${side ? "ei-side" : ""} ${mobileOnly ? "ei-mobile-badge" : ""}`}
    style={{ ...pos, zIndex: z, "--d": d }}
  >
    <div className="ei-float" style={{ "--fd": fd, "--fx": fx, "--fy": fy }}>
      <div
        className={`ei-badge ${dark ? "ei-badge-dark" : "ei-badge-light"}`}
        data-rot={rot}
        onMouseEnter={stickerEnter}
        onMouseLeave={stickerLeave}
        style={{ transform: `rotate(${rot}deg)` }}
      >
        {label}
      </div>
    </div>
  </div>
);

const IconSticker = ({ rot = -4, pos, size = 56, bg = "var(--orange)", Icon, iconSize, z = 30, d = "1.2s", fd = "3.6s", fx = "-4px", fy = "-9px", side = true, mobileOnly = false, border = true }) => (
  <div
    className={`ei-sticker-pos ei-pre ei-a-pop ${side ? "ei-side" : ""} ${mobileOnly ? "ei-mobile-badge" : ""}`}
    style={{ ...pos, zIndex: z, "--d": d }}
  >
    <div className="ei-float" style={{ "--fd": fd, "--fx": fx, "--fy": fy }}>
      <span
        className="ei-icon-sticker"
        data-rot={rot}
        onMouseEnter={stickerEnter}
        onMouseLeave={stickerLeave}
        style={{ width: size, height: size, background: bg, transform: `rotate(${rot}deg)`, border: border ? "4px solid #FFFFFF" : "none" }}
      >
        <Icon size={iconSize || Math.round(size * 0.42)} />
      </span>
    </div>
  </div>
);

const DoodleSpot = ({ pos, width, d = "1.4s", children }) => (
  <div className="ei-doodle ei-pre ei-a-doodle" style={{ ...pos, width, "--d": d }}>
    {children}
  </div>
);

/* Scattered orange doodles to keep light sections lively */
const SectionDoodles = ({ tint = "rgba(240,90,40,0.32)" }) => (
  <>
    <div className="ei-live-doodle ei-float" style={{ left: "3%", top: "12%", width: 30, color: tint, "--fx": "4px", "--fy": "-8px" }} aria-hidden="true"><Doodle.Star /></div>
    <div className="ei-live-doodle" style={{ right: "4%", top: "9%", width: 56, color: tint }} aria-hidden="true"><Doodle.Loop /></div>
    <div className="ei-live-doodle ei-float" style={{ left: "6%", bottom: "12%", width: 24, color: tint, "--fd": "4.2s", "--fx": "-4px", "--fy": "-9px" }} aria-hidden="true"><Doodle.Sparkle /></div>
    <div className="ei-live-doodle" style={{ right: "6%", bottom: "10%", width: 34, color: tint }} aria-hidden="true"><Doodle.Smiley /></div>
    <div className="ei-live-doodle" style={{ left: "46%", top: "5%", width: 44, color: tint, transform: "rotate(14deg)" }} aria-hidden="true"><Squiggle /></div>
  </>
);

/* ------------------------------ Data ------------------------------- */

const NAV_LINKS = ["Home", "Universities", "Scholarships", "Student Q&A", "How We Help", "Malaysia Guide", "About Us"];
