/* Indicative PhD tuition by university type. Masters figures come from
   each university's own fee record above (uni.fees.master). */
const PHD_BAND_BY_CATEGORY = {
  "Public": "USD 4,000 – 9,000 total",
  "Private": "USD 12,000 – 22,000 total",
  "Foreign Branch": "USD 25,000 – 45,000 total",
};

/* Generic, factual blurbs keyed by keyword so course/campus modals have
   real substance without inventing university-specific claims. */
const CAMPUS_DETAIL_BY_KEYWORD = [
  { kw: ["accommodation", "residence", "hostel", "housing", "apartment", "village", "mahallah", "condo"], text: "On-campus or partner housing, typically within walking distance or a short shuttle ride of lecture halls, with options ranging from shared rooms to private studios." },
  { kw: ["library"], text: "A full-service academic library with study pods, group discussion rooms, digital databases, and extended hours during exam periods." },
  { kw: ["sport", "gym", "pool", "stadium", "fitness", "court", "golf", "field", "track"], text: "Dedicated sports facilities for both competitive teams and casual student use, including fitness equipment, courts, and organized leagues." },
  { kw: ["community", "student body", "population", "network", "council", "diverse", "global", "international", "multi-national", "multi-cultural"], text: "A genuinely international student mix, with cultural societies, buddy programs, and orientation support for newly arrived students." },
  { kw: ["club", "societ", "association"], text: "Dozens of student-run clubs and societies covering academics, hobbies, culture, and sport, most open to join from your first week." },
  { kw: ["cafe", "food", "dining", "cafeteria", "restaurant"], text: "On-campus dining outlets and food courts offering halal, international, and budget-friendly options for daily student life." },
];
const campusDetailFor = (label) => {
  const l = label.toLowerCase();
  const hit = CAMPUS_DETAIL_BY_KEYWORD.find((r) => r.kw.some((k) => l.includes(k)));
  return hit ? hit.text : "A core part of everyday campus life that current students rely on.";
};

/* Maps a Campus Life tile label (default GALLERY label or a university's own
   custom "campus" array text) to the correct photo category — matching by
   keyword rather than array position, since custom campus arrays (e.g.
   Monash's) list categories in a different order than GALLERY. */
const CAMPUS_PHOTO_KEYWORDS = [
  { kw: ["library", "study", "learning resource", "learning commons", "resource center", "resource centre"], cat: "library" },
  { kw: ["club", "societ"], cat: "clubs" },
  { kw: ["sport", "gym", "fitness", "recreation", "stadium", "pool"], cat: "sports" },
  { kw: ["housing", "accommodation", "residen", "hostel", "college", "village", "mahallah", "apartment", "condo"], cat: "housing" },
  { kw: ["cafe", "food", "dining", "cafeteria"], cat: "cafe" },
  { kw: ["community", "international", "student body", "diverse", "student network", "student population", "countries represented", "multi-national", "multi-cultural", "global student"], cat: "community" },
];
const campusPhotoFor = (uniName, label) => {
  const photos = CAMPUS_PHOTOS[uniName];
  if (!photos) return null;
  const l = label.toLowerCase();
  const hit = CAMPUS_PHOTO_KEYWORDS.find((r) => r.kw.some((k) => l.includes(k)));
  return hit ? photos[hit.cat] : null;
};

/* Career outcomes by degree — grounded in real course data. We deliberately
   do NOT invent named "alumni" with fabricated photos/companies (that would
   present fake personal endorsements as fact). Instead we show, per real
   course, the kind of role and real, well-known employers that field
   typically leads to — general industry information, not a personal claim
   about any specific graduate. */

/* Map company names to domains for Clearbit logo API */
const COMPANY_LOGOS = {
  "Google": "google.com",
  "Microsoft": "microsoft.com",
  "Maybank": "maybank.com",
  "PwC": "pwc.com",
  "Deloitte": "deloitte.com",
  "Grab": "grab.com",
  "Shopee": "shopee.com",
  "Nestlé": "nestle.com",
  "CIMB": "cimb.com.my",
  "Petronas": "petronas.com.my",
  "Shell": "shell.com",
  "Siemens": "siemens.com",
  "Alstom": "alstom.com",
  "IHH Healthcare": "ihhealthcare.com",
  "Gleneagles": "gleneagles.com.my",
  "Pantai Hospital": "pantai.com.my",
  "Sunway Medical": "sunwaymedical.com.my",
  "Zaid Ibrahim & Co": "zic.com.my",
  "Baker McKenzie": "bakermckenzie.com",
  "Rahmat Lim & Partners": "rlp.com.my",
  "Ogilvy": "ogilvy.com",
  "WPP": "wpp.com",
  "Publicis": "publicis.com",
  "Shangri-La": "shangri-la.com",
  "Marriott": "marriott.com",
  "Genting": "genting.com",
  "Sunway Resort": "sunwayresorts.com",
  "Pfizer": "pfizer.com",
  "AstraZeneca": "astrazeneca.com",
  "Top Glove": "topglove.com.my",
  "British Council": "britishcouncil.org.my",
  "Randstad": "randstad.com.my",
};

/* Locally embedded circular logo badges for companies we have real uploaded
   logos for. Same fixed size, white background, centered — rendered instead
   of the live Clearbit fetch for these specific companies. */
const COMPANY_LOGO_IMAGES = {
  "Nestlé": "data:image/png;base64,",
  "Grab": "data:image/png;base64,",
  "Google": "data:image/png;base64,",
  "CIMB": "data:image/png;base64,",
  "Microsoft": "data:image/png;base64,",
  "Shopee": "data:image/png;base64,",
  "PwC": "data:image/png;base64,",
  "Deloitte": "data:image/png;base64,",
  "Maybank": "data:image/png;base64,",
  "Randstad": "data:image/png;base64,",
  "Shangri-La": "data:image/png;base64,",
  "WPP": "data:image/png;base64,",
  "Publicis": "data:image/png;base64,",
  "Sunway Resort": "data:image/png;base64,",
  "AstraZeneca": "data:image/png;base64,",
  "Top Glove": "data:image/png;base64,",
  "Genting": "data:image/png;base64,",
  "Marriott": "data:image/png;base64,",
  "Ogilvy": "data:image/png;base64,",
  "IHH Healthcare": "data:image/png;base64,",
  "Pantai Hospital": "data:image/png;base64,",
  "Sunway Medical": "data:image/png;base64,",
  "Zaid Ibrahim & Co": "data:image/png;base64,",
  "Baker McKenzie": "data:image/png;base64,",
  "Alstom": "data:image/png;base64,",
  "Siemens": "data:image/png;base64,",
  "Shell": "data:image/png;base64,",
  "Petronas": "data:image/png;base64,",
};

const OUTCOME_BY_KEYWORD = [
  { kw: ["business", "management", "marketing", "real estate", "entrepreneur", "public admin", "mba"], role: "Business Analyst", companies: ["Maybank", "PwC", "Deloitte", "Nestlé"], Icon: Briefcase },
  { kw: ["finance", "accounting", "economics", "actuarial"], role: "Finance Associate", companies: ["Maybank", "PwC", "Deloitte", "CIMB"], Icon: Wallet },
  { kw: ["engineering", "mechanical", "electrical", "civil", "petroleum", "aeronautics", "energy", "electromagnetics", "aviation", "surveying", "marine"], role: "Graduate Engineer", companies: ["Petronas", "Shell", "Siemens", "Alstom"], Icon: Building2 },
  { kw: ["computer", "it", "software", "data", "cyber", "multimedia", "ai", "information", "game"], role: "Software Engineer", companies: ["Google", "Microsoft", "Grab", "Shopee"], Icon: Globe },
  { kw: ["medicine", "medical", "clinical"], role: "Junior Doctor", companies: ["IHH Healthcare", "Gleneagles", "Pantai Hospital", "Sunway Medical"], Icon: HeartIcon },
  { kw: ["health", "nursing", "pharmacy", "dentistry", "biomed", "healthcare", "optometry", "physiotherapy", "pharmaceutical"], role: "Healthcare Professional", companies: ["IHH Healthcare", "Gleneagles", "Pantai Hospital", "Sunway Medical"], Icon: HeartIcon },
  { kw: ["law"], role: "Legal Associate", companies: ["Zaid Ibrahim & Co", "Baker McKenzie", "Rahmat Lim & Partners"], Icon: ShieldCheck },
  { kw: ["design", "art", "media", "architecture", "creative", "communication", "music"], role: "Design Associate", companies: ["Ogilvy", "WPP", "Publicis", "local design studios"], Icon: StarIcon },
  { kw: ["hospitality", "tourism", "culinary", "hotel"], role: "Hospitality Executive", companies: ["Shangri-La", "Marriott", "Genting", "Sunway Resort"], Icon: Coffee },
  { kw: ["science", "biology", "chemistry", "biotech", "geoscience", "geology", "genetics", "bioinformatics", "agriculture", "forestry"], role: "Research Associate", companies: ["Pfizer", "AstraZeneca", "Top Glove", "local R&D institutes"], Icon: Target },
  { kw: ["education", "early childhood", "language", "linguistics"], role: "Education Specialist", companies: ["British Council", "international schools", "education consultancies"], Icon: BookOpen },
  { kw: ["psychology", "social", "politics", "relations", "human resource"], role: "HR / People Associate", companies: ["Randstad", "multinational HR teams", "NGOs"], Icon: Users },
];
const outcomeFor = (course) => {
  const c = course.toLowerCase();
  const hit = OUTCOME_BY_KEYWORD.find((r) => r.kw.some((k) => c.includes(k)));
  return hit || { role: "Graduate Professional", companies: ["regional employers", "MNC graduate programmes"], Icon: GraduationCap };
};
const getOutcomes = (uni) => uni.courses.slice(0, 4).map((course) => ({ course, ...outcomeFor(course) }));

function UniversityDetailPage({ uni, navigate, goBack, openGuidance, openBooking }) {
  if (!uni) return null;
  const [activeModal, setActiveModal] = useState(null); // { kind: "course"|"campus", title, ... }

  // Sticky header: reveal a compact bar once the hero cover has scrolled away.
  const heroRef = useRef(null);
  const [stuck, setStuck] = useState(false);
  useEffect(() => {
    let raf = 0;
    const read = () => {
      raf = 0;
      const el = heroRef.current;
      const past = el ? el.getBoundingClientRect().bottom <= 64 : window.scrollY > 420;
      setStuck((s) => (s === past ? s : past));
    };
    const onScroll = () => { if (!raf) raf = requestAnimationFrame(read); };
    read();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll, { passive: true });
    return () => {
      if (raf) cancelAnimationFrame(raf);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };
  }, [uni.name]);

  // Real fee structure from the directory data (label + amount rows)
  const feeRows = [
    ["Foundation", uni.fees && uni.fees.foundation],
    ["Diploma", uni.fees && uni.fees.diploma],
    ["Bachelor's Degree", uni.fees && uni.fees.bachelor],
    ["Master's Degree", uni.fees && uni.fees.master],
  ].filter((r) => r[1] && r[1] !== "N/A");

  const scholarships = (uni.scholarships && uni.scholarships.length)
    ? uni.scholarships
    : ["Merit Scholarships", "International Student Awards", "EasyIntake Partner Discounts"];

  const requirements = (uni.requirements && uni.requirements.length)
    ? uni.requirements
    : [
      "Completed high school (12 years of education) or equivalent",
      "Official academic transcripts",
      "English proficiency (IELTS / TOEFL / MUET, varies by course)",
      "A valid passport and supporting documents",
    ];

  const campus = (uni.campus && uni.campus.length) ? uni.campus : null;
  const intakeMonths = (uni.intake && uni.intake.length) ? uni.intake : ["February", "September"];
  const outcomes = getOutcomes(uni);
  const cover = UNI_COVERS_HERO[uni.name] || UNI_COVERS[uni.name];
  const heroBg = cover
    ? `linear-gradient(100deg, ${uni.color}E6 0%, ${uni.color}99 32%, rgba(13,15,17,0.35) 62%, rgba(13,15,17,0.15) 100%), url(${cover})`
    : `radial-gradient(120% 100% at 15% 0%, ${uni.color} 0%, rgba(0,0,0,0) 60%), radial-gradient(130% 120% at 90% 100%, #101418 0%, rgba(16,20,24,0) 65%), ${uni.color}`;

  return (
    <>
      {/* ---------- sticky header (compact logo + name) ---------- */}
      <div className={`ei-d-sticky ${stuck ? "ei-d-sticky-on" : ""}`} aria-hidden={!stuck}>
        <div className="ei-d-sticky-inner">
          <UniLogo name={uni.name} color={uni.color} size={32} />
          <span className="ei-d-sticky-name">{uni.name}</span>
          <button type="button" className="ei-d-sticky-back" onClick={goBack}>
            <ChevronLeft size={14} /> All Universities
          </button>
        </div>
      </div>

      {/* ---------- detail hero ---------- */}
      <div className="ei-shell" ref={heroRef}>
        <section
          className="ei-d-hero ei-block"
          style={
            cover
              ? { backgroundImage: heroBg, backgroundSize: "cover", backgroundPosition: COVER_FOCAL[uni.name] || "center" }
              : { background: heroBg }
          }
        >
          <div className="ei-d-hero-inner">
            <button type="button" className="ei-d-back ei-pre ei-a-rise" style={{ "--d": "0.1s" }} onClick={goBack}>
              <ChevronLeft size={15} /> All Universities
            </button>
            <UniLogo
              name={uni.name}
              color={uni.color}
              size={96}
              className={`ei-d-hero-logo ei-pre ei-a-pop ${cover ? "ei-d-mono-cover" : ""}`}
              style={{ "--d": "0.25s" }}
            />
            <h1 className="ei-d-name ei-pre ei-a-rise" style={{ "--d": "0.35s" }}>{uni.name}</h1>
            <div className="ei-d-meta ei-pre ei-a-rise" style={{ "--d": "0.48s" }}>
              <span className="ei-d-chip"><MapPin size={15} /> {uni.location}</span>
              <span className="ei-d-chip"><Building2 size={15} /> {uni.type === "Foreign" ? "Foreign Branch Campus" : uni.type + " University"}</span>
              {getUniRank(uni) && (
                <span className="ei-d-chip">
                  {getUniRank(uni).kind === "rank" ? <Award size={15} /> : <LucideStar size={15} fill="currentColor" />}
                  {getUniRank(uni).label}
                </span>
              )}
            </div>
            <div className="ei-d-cta-row ei-pre ei-a-rise" style={{ "--d": "0.6s" }}>
              <a href="https://api.leadconnectorhq.com/widget/survey/oICk3R6Jw3DEls3KtKTv" target="_blank" rel="noopener noreferrer" className="ei-btn-white">
                Get Free Guidance <ArrowRight size={17} />
              </a>
            </div>
          </div>
        </section>
      </div>

      {/* ---------- overview ---------- */}
      <div className="ei-shell">
        <section className="ei-block" style={{ background: "var(--cream)" }}>
          <SectionDoodles tint="rgba(240,90,40,0.28)" />
          <div className="ei-wrap" style={{ paddingTop: 64, paddingBottom: 64 }}>
            <h2 className="ei-d-title" data-reveal>Overview</h2>
            <p className="ei-d-body" data-reveal style={{ "--d": "0.08s" }}>
              {uni.about}
            </p>
          </div>
        </section>
      </div>

      {/* ---------- intake periods ---------- */}
      <div className="ei-shell">
        <section className="ei-block" style={{ background: "#FFFFFF", border: "1px solid #EFE9DE" }}>
          <SectionDoodles tint="rgba(240,90,40,0.26)" />
          <div className="ei-wrap" style={{ paddingTop: 64, paddingBottom: 64 }}>
            <h2 className="ei-d-title" data-reveal>Intake Periods</h2>
            <p className="ei-d-body" data-reveal style={{ "--d": "0.05s", marginBottom: 8 }}>
              Here's when you can start at {uni.name}, think of each stop as a boarding gate for your journey.
            </p>
            <div className="ei-intake-strip" data-reveal style={{ "--d": "0.1s" }}>
              <div className="ei-intake-track">
                {intakeMonths.map((m, i) => (
                  <React.Fragment key={m}>
                    {i > 0 && (
                      <span className="ei-intake-connector" aria-hidden="true">
                        <ArrowRight size={15} />
                      </span>
                    )}
                    <div
                      className="ei-intake-ticket"
                      style={{ "--bar": i % 2 === 0 ? uni.color : "var(--orange)" }}
                    >
                      <span className="ei-intake-plane" style={{ background: i % 2 === 0 ? uni.color : "var(--orange)" }}>
                        <PlaneIcon size={19} />
                      </span>
                      <div className="ei-intake-seq">Intake {String(i + 1).padStart(2, "0")}</div>
                      <div className="ei-intake-month">{m}</div>
                      <div className="ei-intake-divider" />
                      <span className="ei-intake-tag" style={{ "--bar": i % 2 === 0 ? uni.color : "var(--orange)" }}>
                        <Check size={12} /> Open For Entry
                      </span>
                    </div>
                  </React.Fragment>
                ))}
              </div>
            </div>
            <p className="ei-intake-note" data-reveal style={{ "--d": "0.2s" }}>
              <Clock size={16} />
              <span>
                Intake months shift slightly year to year and by course level (foundation, diploma, bachelor's, master's).
                Ask us for the exact application deadline for your intended intake, we track this for every course.
              </span>
            </p>
          </div>
        </section>
      </div>

      {/* ---------- campus video ----------
           Only rendered when the university actually has a verified video.
           Universities without one simply skip this section rather than
           showing an empty placeholder or a YouTube search link. */}
      {uni.youtubeId && (
        <div className="ei-shell">
          <section className="ei-block" style={{ background: "#FFFFFF", border: "1px solid #EFE9DE" }}>
            <SectionDoodles tint="rgba(13,31,61,0.16)" />
            <div className="ei-wrap" style={{ paddingTop: 64, paddingBottom: 64, textAlign: "center" }}>
              <h2 className="ei-d-title" data-reveal>See the Campus</h2>
              <div className="ei-d-video-player" data-reveal style={{ "--d": "0.08s", margin: "0 auto", maxWidth: 860 }}>
                <iframe
                  src={`https://www.youtube.com/embed/${uni.youtubeId}`}
                  title={`${uni.name} campus video`}
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                />
              </div>
              <p className="ei-d-body" data-reveal style={{ marginTop: 14, fontSize: 13, "--d": "0.14s", marginLeft: "auto", marginRight: "auto" }}>
                An official campus video for {uni.name}, playing right here.
              </p>
            </div>
          </section>
        </div>
      )}

      {/* ---------- popular courses ---------- */}
      <div className="ei-shell">
        <section className="ei-block" style={{ background: "#FFFFFF", border: "1px solid #EFE9DE" }}>
          <SectionDoodles tint="rgba(240,90,40,0.26)" />
          <div className="ei-wrap" style={{ paddingTop: 64, paddingBottom: 64 }}>
            <h2 className="ei-d-title" data-reveal>Popular Courses</h2>
            <div className="ei-d-course-grid">
              {uni.courses.map((c, i) => {
                const oc = outcomeFor(c);
                return (
                  <button
                    type="button"
                    className="ei-d-course"
                    data-reveal
                    key={c}
                    style={{ "--d": `${i * 0.08}s` }}
                    onClick={() => setActiveModal({ kind: "course", title: c, role: oc.role, companies: oc.companies, Icon: oc.Icon, color: COURSE_COLORS[i % COURSE_COLORS.length] })}
                  >
                    <span className="ei-d-course-ic" style={{ background: COURSE_COLORS[i % COURSE_COLORS.length] }}>
                      <GraduationCap size={22} />
                    </span>
                    {c}
                  </button>
                );
              })}
            </div>
          </div>
        </section>
      </div>

      {/* ---------- tuition fees ---------- */}
      <div className="ei-shell">
        <section className="ei-block" style={{ background: "var(--cream)" }}>
          <SectionDoodles tint="rgba(13,31,61,0.16)" />
          <div className="ei-wrap" style={{ paddingTop: 64, paddingBottom: 64 }}>
            <h2 className="ei-d-title" data-reveal>Tuition Fees</h2>
            <div data-reveal style={{ "--d": "0.08s", overflowX: "auto" }}>
              <table className="ei-table">
                <thead>
                  <tr><th>Study Level</th><th>Estimated Fees</th></tr>
                </thead>
                <tbody>
                  {feeRows.map((r) => (
                    <tr key={r[0]}>
                      <td>{r[0]}</td>
                      <td className="ei-fee">{r[1]}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p className="ei-d-body" data-reveal style={{ marginTop: 16, fontSize: 13, "--d": "0.16s" }}>
              Indicative international-student fees, they vary by program and intake. Ask us for the exact fee for your course, scholarships can lower these significantly.
            </p>
          </div>
        </section>
      </div>

      {/* ---------- scholarships ---------- */}
      <div className="ei-shell">
        <section className="ei-block" style={{ background: "#FFFFFF", border: "1px solid #EFE9DE" }}>
          <SectionDoodles tint="rgba(240,90,40,0.26)" />
          <div className="ei-wrap" style={{ paddingTop: 64, paddingBottom: 64 }}>
            <h2 className="ei-d-title" data-reveal>Scholarships</h2>
            <div className="ei-schol">
              {scholarships.map((s, i) => (
                <div className="ei-schol-item" data-reveal key={i} style={{ "--d": `${i * 0.07}s` }}>
                  <BadgeCheck size={19} /> {s}
                </div>
              ))}
            </div>
          </div>
        </section>
      </div>

      {/* ---------- career outcomes ---------- */}
      <div className="ei-shell">
        <section className="ei-block" style={{ background: "var(--cream)" }}>
          <SectionDoodles tint="rgba(13,31,61,0.16)" />
          <div className="ei-wrap" style={{ paddingTop: 64, paddingBottom: 64 }}>
            <h2 className="ei-d-title" data-reveal>Where a Degree Here Can Take You</h2>
            <div className="ei-d-outcome-grid">
              {outcomes.map((o, i) => (
                <div className="ei-d-outcome-card" data-reveal key={o.course} style={{ "--d": `${0.06 + i * 0.08}s` }}>
                  <span className="ei-d-outcome-icon" style={{ background: uni.color }}>
                    <o.Icon size={22} />
                  </span>
                  <div className="ei-d-outcome-degree"><GraduationCap size={13} /> {o.course}</div>
                  <div className="ei-d-outcome-role">{o.role}</div>
                  <div className="ei-d-outcome-companies-label">Typical Employers</div>
                  <div className="ei-d-outcome-chips">
                    {o.companies.map((c) => (
                      <span className="ei-d-outcome-chip" key={c}>
                        {COMPANY_LOGO_IMAGES[c] ? (
                          <img
                            src={COMPANY_LOGO_IMAGES[c]}
                            alt={c}
                            className="ei-d-outcome-chip-logo"
                            loading="lazy"
                          />
                        ) : COMPANY_LOGOS[c] ? (
                          <img
                            src={`https://logo.clearbit.com/${COMPANY_LOGOS[c]}?size=20`}
                            alt={c}
                            className="ei-d-outcome-chip-logo"
                            loading="lazy"
                            onError={(e) => {
                              e.target.style.display = "none";
                            }}
                          />
                        ) : (
                          <span className="ei-d-outcome-chip-badge" style={{ background: uni.color }}>{monogram(c)}</span>
                        )}
                        {c}
                      </span>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      </div>

      {/* ---------- campus life ---------- */}
      <div className="ei-shell">
        <section className="ei-block" style={{ background: "var(--cream)" }}>
          <SectionDoodles tint="rgba(240,90,40,0.26)" />
          <div className="ei-wrap" style={{ paddingTop: 64, paddingBottom: 64 }}>
            <h2 className="ei-d-title" data-reveal>Campus Life</h2>
            <div className="ei-gal">
              {(campus || GALLERY.map((g) => g.label)).map((label, i) => {
                const Icon = GALLERY[i % GALLERY.length].Icon;
                const style = CAMPUS_STYLES[i % CAMPUS_STYLES.length];
                const doodleUrl = `url("data:image/svg+xml,${encodeURIComponent(style.doodle)}")`;
                const photo = campusPhotoFor(uni.name, label);
                return (
                  <button
                    type="button"
                    className="ei-gal-tile"
                    data-reveal
                    key={i}
                    style={{
                      "--d": `${i * 0.06}s`,
                      background: style.gradient,
                      "--doodle": doodleUrl,
                    }}
                    onClick={() => setActiveModal({ kind: "campus", title: label, Icon, text: campusDetailFor(label), photo })}
                  >
                    {photo && (
                      <span className="ei-gal-thumb" aria-hidden="true">
                        <img src={photo} alt="" loading="lazy" decoding="async" />
                      </span>
                    )}
                    <Icon size={26} />
                    {label}
                  </button>
                );
              })}
            </div>
          </div>
        </section>
      </div>

      {/* ---------- admission requirements ---------- */}
      <div className="ei-shell">
        <section className="ei-block" style={{ background: "#FFFFFF", border: "1px solid #EFE9DE" }}>
          <SectionDoodles tint="rgba(13,31,61,0.16)" />
          <div className="ei-wrap" style={{ paddingTop: 64, paddingBottom: 64 }}>
            <h2 className="ei-d-title" data-reveal>Admission Requirements</h2>
            <div className="ei-req-grid">
              {requirements.map((r, i) => (
                <div className="ei-check-item" data-reveal key={i} style={{ "--d": `${i * 0.06}s` }}>
                  <span className="ei-check-dot"><Check size={18} /></span>
                  <p>{r}</p>
                </div>
              ))}
            </div>
          </div>
        </section>
      </div>

      {/* ---------- detail CTA ---------- */}
      <div className="ei-shell">
        <section className="ei-ab-cta ei-block" data-reveal>
          <IconSticker Icon={MessageCircle} bg="var(--navy)" rot={7} size={54} iconSize={22} pos={{ right: "6%", top: "8%" }} z={5} d="0.2s" fd="3.4s" side={false} />
          <div className="ei-ab-cta-content" style={{ textAlign: "center" }}>
            <h3>Interested In This University?</h3>
            <p style={{ marginLeft: "auto", marginRight: "auto" }}>
              Tell us you're considering {uni.name} and we'll send you a tailored course
              presentation, entry requirements, and the scholarships you qualify for, all free.
            </p>
            <div className="ei-cta-actions" style={{ marginTop: 28 }}>
              <a href="https://api.leadconnectorhq.com/widget/survey/oICk3R6Jw3DEls3KtKTv" target="_blank" rel="noopener noreferrer" className="ei-btn-white">
                <FileText size={17} /> Get Free Guidance <ArrowRight size={17} />
              </a>
            </div>
          </div>
          <svg className="ei-ab-cta-plane" viewBox="0 0 140 96" aria-hidden="true">
            <path d="M6 88 C 34 76, 44 52, 46 40" fill="none" stroke="currentColor" strokeWidth="3" strokeDasharray="2 8" strokeLinecap="round" />
            <path d="M46 38 132 8 84 52 Z M84 52 132 8 96 74 84 58 Z M84 52 84 78 92 66" fill="none" stroke="currentColor" strokeWidth="3.5" strokeLinejoin="round" />
          </svg>
        </section>
      </div>

      {/* ---------- course / campus detail modal ---------- */}
      {activeModal && (() => {
        const cd = activeModal.kind === "course"
          ? (COURSE_DETAILS[uni.name] || {})[activeModal.title]
          : null;
        return (
          <div className="ei-modal-overlay" onClick={() => setActiveModal(null)}>
            <div className={"ei-modal-card" + (activeModal.kind === "course" ? " ei-cd" : "") + (activeModal.kind === "campus" && activeModal.photo ? " ei-gal-modal" : "")} onClick={(e) => e.stopPropagation()}>
              <button type="button" className="ei-modal-close" aria-label="Close" onClick={() => setActiveModal(null)}>
                <X size={18} />
              </button>
              {!(activeModal.kind === "campus" && activeModal.photo) && (
                <span className="ei-modal-icon" style={{ background: activeModal.color || uni.color }}>
                  <activeModal.Icon size={26} />
                </span>
              )}
              {activeModal.kind === "course" ? (
                <>
                  <div className="ei-modal-eyebrow">Popular Course at {uni.name}</div>
                  <h3 className="ei-modal-title">{cd ? cd.t : activeModal.title}</h3>

                  {cd && cd.ds && <p className="ei-cd-desc">{cd.ds}</p>}

                  {cd && (
                    <div className="ei-cd-tags">
                      {cd.q && <span className="ei-cd-tag"><GraduationCap size={13} /> {cd.q}</span>}
                      {cd.d && <span className="ei-cd-tag"><Clock size={13} /> {cd.d}</span>}
                      {cd.m && <span className="ei-cd-tag"><ClipboardList size={13} /> {cd.m}</span>}
                      {cd.i && <span className="ei-cd-tag"><Calendar size={13} /> {cd.i}</span>}
                    </div>
                  )}

                  {cd && (cd.cl || cd.cf) && (
                    <>
                      <div className="ei-cd-h"><Wallet size={13} /> Estimated Total Cost</div>
                      <div className="ei-cd-fees">
                        {cd.cl && (
                          <div className="ei-cd-fee">
                            <div className="ei-cd-fee-l">Malaysian Student</div>
                            <div className="ei-cd-fee-v">{cd.cl}</div>
                          </div>
                        )}
                        {cd.cf && (
                          <div className="ei-cd-fee">
                            <div className="ei-cd-fee-l">International Student</div>
                            <div className="ei-cd-fee-v">{cd.cf}</div>
                          </div>
                        )}
                      </div>
                    </>
                  )}

                  {cd && cd.e && cd.e.length > 0 && (
                    <>
                      <div className="ei-cd-h"><ClipboardList size={13} /> Entry Requirements</div>
                      <ul className="ei-cd-list">
                        {cd.e.map((r, i) => (
                          <li className="ei-cd-li" key={i}><Check size={15} strokeWidth={3} />{r}</li>
                        ))}
                      </ul>
                    </>
                  )}

                  {cd && cd.en && (
                    <>
                      <div className="ei-cd-h"><Globe size={13} /> English Requirement</div>
                      <div className="ei-cd-eng">{cd.en}</div>
                    </>
                  )}

                  {cd && cd.c && cd.c.length > 0 && (
                    <>
                      <div className="ei-cd-h"><BookOpen size={13} /> What You'll Study</div>
                      <ul className="ei-cd-list">
                        {cd.c.map((r, i) => (
                          <li className="ei-cd-li" key={i}><Check size={15} strokeWidth={3} />{r}</li>
                        ))}
                      </ul>
                    </>
                  )}

                  {/* postgraduate pathway */}
                  <div className="ei-cd-pg">
                    <div className="ei-cd-pg-h"><School size={13} /> Continuing after your degree</div>
                    <div className="ei-cd-pg-grid">
                      <div className="ei-cd-pg-card">
                        <div className="ei-cd-pg-t">Master's</div>
                        <div className="ei-cd-pg-v">
                          1–2 years, coursework plus a dissertation. Entry: a related bachelor's degree at CGPA 2.50–3.00,
                          or relevant work experience. From {uni.fees.master} at {uni.name.split(" (")[0]}.
                        </div>
                      </div>
                      <div className="ei-cd-pg-card">
                        <div className="ei-cd-pg-t">PhD</div>
                        <div className="ei-cd-pg-v">
                          3–5 years of supervised research. Entry: a master's degree, a research proposal, and a matched
                          supervisor. Indicative {PHD_BAND_BY_CATEGORY[uni.category] || PHD_BAND_BY_CATEGORY.Private}.
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="ei-d-outcome-companies-label" style={{ marginTop: 24 }}>Typical Employers</div>
                  <div className="ei-modal-company-row">
                    {activeModal.companies.map((c) => (
                      <span className="ei-modal-company" key={c}>
                        <span className="ei-modal-company-badge" style={{ background: uni.color }}>{monogram(c)}</span>
                        {c}
                      </span>
                    ))}
                  </div>
                  <div className="ei-modal-role" style={{ marginTop: 12 }}><Briefcase size={14} /> Typical path: {activeModal.role}</div>

                  <p className="ei-cd-note">
                    {cd
                      ? "Fees, intakes and entry grades are compiled from published university listings and change between semesters. We confirm every figure with the faculty before you apply. Postgraduate figures are indicative."
                      : "Ask us for the exact modules, entry grades, and intake dates for this course."}
                  </p>
                  <a href="https://api.leadconnectorhq.com/widget/survey/oICk3R6Jw3DEls3KtKTv" target="_blank" rel="noopener noreferrer" className="ei-btn-dark" style={{ marginTop: 14 }} onClick={() => setActiveModal(null)}>
                    Ask About This Course <ArrowRight size={16} />
                  </a>
                </>
              ) : (
                <>
                  {activeModal.photo ? (
                    <>
                      <img src={activeModal.photo} alt={activeModal.title} className="ei-gal-modal-photo" />
                      <div className="ei-modal-eyebrow" style={{ marginTop: 18 }}>Campus Life at {uni.name}</div>
                      <h3 className="ei-modal-title">{activeModal.title}</h3>
                    </>
                  ) : (
                    <>
                      <div className="ei-modal-eyebrow">Campus Life at {uni.name}</div>
                      <h3 className="ei-modal-title">{activeModal.title}</h3>
                      <p className="ei-modal-note" style={{ marginTop: 10 }}>{activeModal.text}</p>
                    </>
                  )}
                </>
              )}
            </div>
          </div>
        );
      })()}

    </>
  );
}


/* ------------------------------ How We Help Page ------------------------------- */
/* Scroll-driven airplane navigation inspired by Google Maps route tracking:      */
/* SVG flight path + getPointAtLength sampling + lerped rAF loop for momentum.    */

const HW_STOPS = [
  {
    n: "01", title: "University & Course Selection", art: "hwstop1",
    body: "Choosing the right university isn't about picking the most famous name. It's about finding the right fit for your goals, budget, academic background, and future career plans."
  },
  {
    n: "02", title: "Application Assistance", art: "hwstop2",
    body: "We help you prepare, review, and submit your application correctly the first time, reducing delays and improving your chances of a smooth admission process."
  },
  {
    n: "03", title: "Visa & Documentation Guidance", art: "hwstop3",
    body: "Visa requirements can be confusing. We guide you through every required document and review everything before submission."
  },
  {
    n: "04", title: "Pre-Departure Support", art: "hwstop4",
    body: "Once you're admitted, we help you prepare for life in Malaysia, from accommodation guidance to arrival planning and practical tips."
  },
  {
    n: "05", title: "Ongoing Support in Malaysia", art: "hwstop5",
    body: "Our support doesn't end when you land. If you have questions during your first weeks in Malaysia, we're still here to help."
  },
];
const HW_W = 1000, HW_H = 1800;
const HW_STOP_Y = [200, 480, 760, 1040, 1320];
const HW_PATH = "M 180 -20 C 180 80, 252 120, 250 200 C 248 270, 130 285, 130 340 C 130 395, 252 410, 251 480 C 250 550, 129 565, 129 620 C 129 675, 252 690, 251 760 C 250 830, 128 845, 128 900 C 128 955, 252 970, 251 1040 C 250 1110, 127 1125, 127 1180 C 127 1235, 251 1250, 250 1320 C 249 1400, 340 1480, 470 1560";

const StampSVG = ({ label, sub = "Approved" }) => (
  <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%" }} aria-hidden="true">
    <circle cx="50" cy="50" r="45" fill="none" stroke="#F05A28" strokeWidth="3.5" strokeDasharray="4 5" />
    <circle cx="50" cy="50" r="33" fill="none" stroke="#F05A28" strokeWidth="2" />
    <text x="50" y="44" textAnchor="middle" fill="#F05A28" fontFamily="'Bricolage Grotesque', sans-serif" fontWeight="800" fontSize="13">{label}</text>
    <text x="50" y="62" textAnchor="middle" fill="#F05A28" fontFamily="'Bricolage Grotesque', sans-serif" fontWeight="800" fontSize="11" letterSpacing="1">{sub.toUpperCase()}</text>
  </svg>
);

const MYFlag = ({ w = 42 }) => (
  <span className="ei-hw-flag" style={{ width: w, height: w * 0.55 }}>
    <svg viewBox="0 0 42 23" style={{ display: "block", width: "100%", height: "100%" }} aria-label="Flag of Malaysia" role="img">
      <rect width="42" height="23" fill="#FFFFFF" />
      {[0, 2, 4, 6, 8, 10, 12].map((i) => (
        <rect key={i} y={i * (23 / 14)} width="42" height={23 / 14} fill="#CC0001" />
      ))}
      <rect width="21" height={23 * 8 / 14} fill="#010066" />
      <circle cx="8.6" cy="6.6" r="4.4" fill="#FFCC00" />
      <circle cx="10.4" cy="6.6" r="3.7" fill="#010066" />
      <path d="M15.8 6.6 l3.4 1.1 -2.1-2.9 0 3.6 -2.1-2.9 Z" fill="#FFCC00" transform="rotate(18 15.8 6.6)" />
    </svg>
  </span>
);

function HowWeHelpPage({ navigate, openGuidance, openBooking }) {
  const heroJetRef = useRef(null);
  const zoneRef = useRef(null);
  const pathRef = useRef(null);
  const clipAheadRef = useRef(null);
  const clipTrailRef = useRef(null);
  const planeRef = useRef(null);
  const passRef = useRef(null);
  const stopRefs = useRef([]);

  /* hero jet: takes off across the hero as the user scrolls */
  useEffect(() => {
    const jet = heroJetRef.current;
    if (!jet) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let raf = 0;
    const update = () => {
      raf = 0;
      const k = Math.min(1, window.scrollY / 520);
      const e = 1 - Math.pow(1 - k, 3);
      jet.style.transform = `translate(${(e * 300).toFixed(1)}px, ${(e * -120).toFixed(1)}px) rotate(${(-8 + e * 16).toFixed(1)}deg)`;
      jet.style.opacity = String(1 - e * 0.25);
    };
    const onScroll = () => { if (!raf) raf = requestAnimationFrame(update); };
    window.addEventListener("scroll", onScroll, { passive: true });
    update();
    return () => { window.removeEventListener("scroll", onScroll); if (raf) cancelAnimationFrame(raf); };
  }, []);

  useEffect(() => {
    const zone = zoneRef.current, path = pathRef.current, plane = planeRef.current;
    if (!zone || !path || !plane) return;
    const desktop = window.matchMedia("(min-width: 900px)");
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    /* mobile / reduced motion: everything visible, no engine */
    if (!desktop.matches || reduceMotion) {
      stopRefs.current.forEach((el) => el && el.classList.add("ei-hw-done"));
      if (passRef.current) passRef.current.classList.add("ei-hw-pass-landed");
      return;
    }

    const L = path.getTotalLength();
    /* fraction along the path for each stop (sampled by y) */
    const stopFrac = HW_STOP_Y.map((y) => {
      let best = 0, bestD = Infinity;
      for (let i = 0; i <= 300; i++) {
        const pt = path.getPointAtLength((i / 300) * L);
        const d = Math.abs(pt.y - y);
        if (d < bestD) { bestD = d; best = i / 300; }
      }
      return best;
    });

    let cur = 0, target = 0, rafId = 0, landed = false;
    const tick = (time) => {
      const rect = zone.getBoundingClientRect();
      const vh = window.innerHeight;
      target = Math.min(1, Math.max(0, (vh * 0.55 - rect.top) / rect.height));
      cur += (target - cur) * 0.09; /* momentum */

      const sx = rect.width / HW_W, sy = rect.height / HW_H;
      const l = cur * L;
      const p = path.getPointAtLength(l);
      const pa = path.getPointAtLength(Math.min(L, l + 6));
      const pb = path.getPointAtLength(Math.max(0, l - 6));
      const ang = Math.atan2((pa.y - pb.y) * sy, (pa.x - pb.x) * sx) * 180 / Math.PI;
      const bob = Math.sin(time * 0.0035) * 4;
      const tilt = Math.sin(time * 0.0028) * 3;
      const px = p.x * sx, py = p.y * sy + (landed ? 0 : bob);
      const heading = ang + 10; /* jet art noses right (~-10deg); +10 aligns nose with travel */
      plane.style.transform = `translate(${(px - 46).toFixed(1)}px, ${(py - 20).toFixed(1)}px) rotate(${(landed ? 10 : heading + tilt).toFixed(1)}deg)`;

      /* progressive path draw: ahead + trail clips */
      if (clipAheadRef.current) clipAheadRef.current.setAttribute("height", String(Math.min(1, cur + 0.1) * HW_H + 40));
      if (clipTrailRef.current) clipTrailRef.current.setAttribute("height", String(cur * HW_H + 20));

      /* stop states */
      stopRefs.current.forEach((el, i) => {
        if (!el) return;
        const f = stopFrac[i];
        el.classList.toggle("ei-hw-done", cur > f + 0.03);
        el.classList.toggle("ei-hw-active", Math.abs(cur - f) <= 0.04);
      });

      /* landing */
      if (cur > 0.965 && !landed) {
        landed = true;
        plane.classList.add("ei-hw-landed");
        if (passRef.current) passRef.current.classList.add("ei-hw-pass-landed");
      } else if (cur < 0.9 && landed) {
        landed = false;
        plane.classList.remove("ei-hw-landed");
      }

      rafId = requestAnimationFrame(tick);
    };
    rafId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafId);
  }, []);

  return (
    <>
      {/* ---------- hero ---------- */}
      <main className="ei-main">
        <section className="ei-card ei-ab-card" style={{ paddingBottom: 100 }}>
          <div className="ei-bglayer" aria-hidden="true">
            <div className="ei-mesh" />
            <div className="ei-blob" style={{
              width: 520, height: 520, left: "-10%", top: "-20%", "--bx": "70px", "--by": "40px", "--bs": "1.15", "--bd": "9s",
              background: "radial-gradient(circle, rgba(255,170,110,0.85) 0%, rgba(255,170,110,0) 65%)"
            }} />
            <div className="ei-blob" style={{
              width: 560, height: 560, right: "-14%", bottom: "-30%", "--bx": "-60px", "--by": "-40px", "--bs": "0.92", "--bd": "11s", "--bdel": "0.7s",
              background: "radial-gradient(circle, rgba(200,60,14,0.75) 0%, rgba(200,60,14,0) 65%)"
            }} />
            <div className="ei-glowline" />
          </div>
          <div className="ei-grain" aria-hidden="true" />
          <IconSticker Icon={HeartIcon} bg="var(--orange)" rot={8} size={50} iconSize={20} pos={{ left: "3%", bottom: "6%" }} z={18} d="1.1s" fd="3.6s" />

          <div className="ei-u-hero-grid">
            <div className="ei-u-left">
              <span className="ei-ab-chip ei-pre ei-a-rise" style={{ "--d": "0.2s" }}>How We Help</span>
              <h1 className="ei-ab-h1 ei-pre ei-a-rise" style={{ "--d": "0.35s" }}>
                Everything You Need to Study in Malaysia, In One Place
              </h1>
              <p className="ei-ab-sub ei-pre ei-a-rise" style={{ "--d": "0.5s" }}>
                From your first question to your first day of class, we're here to guide you
                through every step of the journey.
              </p>
              <div className="ei-u-ctas ei-pre ei-a-rise" style={{ "--d": "0.62s" }}>
                <a href="https://api.leadconnectorhq.com/widget/booking/dNgEYHHdDDzwv4Hgn3Dy" target="_blank" rel="noopener noreferrer" className="ei-btn-white">
                  <Calendar size={16} /> Start Your Application <ArrowRight size={17} />
                </a>
              </div>
            </div>

            <div className="ei-u-collage ei-pre ei-a-pop" style={{ "--d": "0.72s", height: 470 }}>
              {/* only three elements: big map behind-right, big taped KL polaroid in front,
                  jet that flies away as you scroll */}
              <div className="ei-u-art" data-rot="4" onMouseEnter={stickerEnter} onMouseLeave={stickerLeave} style={{ right: "-3%", top: "-2%", width: "66%", transform: "rotate(4deg)", zIndex: 1 }}>
                <img src={UNI_ART.hwmap} alt="Vintage Malaysia map sticker" draggable="false" />
              </div>
              <div className="ei-u-art" data-rot="-6" onMouseEnter={stickerEnter} onMouseLeave={stickerLeave} style={{ left: "2%", top: "8%", width: "56%", transform: "rotate(-6deg)", zIndex: 3 }}>
                <img src={STICKERS.s5} alt="Kuala Lumpur polaroid sticker" draggable="false" />
              </div>
              <div className="ei-u-art" ref={heroJetRef} style={{ left: "-5%", top: "58%", width: "40%", transform: "rotate(-8deg)", zIndex: 5, cursor: "default" }}>
                <img src={UNI_ART.jet} alt="Airplane sticker" draggable="false" />
              </div>
            </div>
          </div>
        </section>
      </main>

      {/* ---------- flight journey ---------- */}
      <section className="ei-hw-zone" ref={zoneRef}>
        <div className="ei-hw-journey">
          {/* flight path: faint route + ahead-draw + vivid trail */}
          <svg className="ei-hw-svg" viewBox={`0 0 ${HW_W} ${HW_H}`} preserveAspectRatio="none" aria-hidden="true">
            <defs>
              <clipPath id="hwAhead"><rect ref={clipAheadRef} x="0" y="0" width={HW_W} height="0" /></clipPath>
              <clipPath id="hwTrail"><rect ref={clipTrailRef} x="0" y="0" width={HW_W} height="0" /></clipPath>
            </defs>
            <path ref={pathRef} d={HW_PATH} fill="none" stroke="#D9C6A8" strokeWidth="3" strokeDasharray="1 14" strokeLinecap="round" opacity="0.55" />
            <path d={HW_PATH} fill="none" stroke="#C79A6B" strokeWidth="3.5" strokeDasharray="1 14" strokeLinecap="round" clipPath="url(#hwAhead)" />
            <path d={HW_PATH} fill="none" stroke="#F05A28" strokeWidth="4" strokeDasharray="1 13" strokeLinecap="round" clipPath="url(#hwTrail)" />
          </svg>

          <div className="ei-live-doodle ei-float" style={{ left: "42%", top: "3%", width: 30, color: "rgba(240,90,40,0.4)", "--fx": "5px", "--fy": "-10px" }} aria-hidden="true"><Doodle.Star /></div>
          <div className="ei-live-doodle ei-float" style={{ right: "38%", bottom: "20%", width: 26, color: "rgba(240,90,40,0.4)", "--fd": "4.4s" }} aria-hidden="true"><Doodle.Sparkle /></div>

          {/* faded travel stamps in the background */}
          <div className="ei-hw-bgstamp" style={{ left: "1.5%", top: "20%", transform: "rotate(-14deg)", borderRadius: 999 }}>Kuala Lumpur ✈ Arrival</div>
          <div className="ei-hw-bgstamp" style={{ left: "1%", top: "47%", transform: "rotate(-8deg)" }}>Visa ✻ Malaysia</div>
          <div className="ei-hw-bgstamp" style={{ right: "1%", top: "34%", transform: "rotate(10deg)", borderRadius: 999 }}>Approved ✓</div>
          <div className="ei-hw-bgstamp" style={{ right: "2%", top: "60%", transform: "rotate(-9deg)" }}>Departure ✈</div>
          <div className="ei-hw-bgstamp" style={{ right: "3%", top: "84%", transform: "rotate(8deg)", borderRadius: 999 }}>Welcome ♥ Malaysia</div>

          {/* the airplane */}
          <div className="ei-hw-plane" ref={planeRef}>
            <img src={UNI_ART.jet} alt="" draggable="false" />
            <span className="ei-hw-dust" aria-hidden="true"><span /><span /><span /></span>
          </div>

          {/* five journey stops */}
          {HW_STOPS.map((s, i) => (
            <div
              className="ei-hw-stop"
              key={s.n}
              ref={(el) => { stopRefs.current[i] = el; }}
              style={{ top: `${(HW_STOP_Y[i] / HW_H) * 100}%` }}
            >
              <div className="ei-hw-card">
                <span className="ei-hw-num">{s.n}</span>
                <div className="ei-hw-art" data-rot={i % 2 ? 6 : -6} onMouseEnter={stickerEnter} onMouseLeave={stickerLeave} style={{ transform: `rotate(${i % 2 ? 6 : -6}deg)` }}>
                  <img src={UNI_ART[s.art] || STICKERS[s.art]} alt="" draggable="false" />
                </div>
                <div>
                  <h3 className="ei-hw-title">{s.title}</h3>
                  <p>{s.body}</p>
                </div>
                <span className="ei-hw-stamp"><StampSVG label={`Stop ${s.n}`} sub="Approved" /></span>
              </div>
            </div>
          ))}
        </div>

        {/* ---------- boarding pass finale ---------- */}
        <div className="ei-hw-pass-wrap">
          <div className="ei-hw-pass" ref={passRef} data-reveal>
            <span className="ei-hw-notch" style={{ left: -18, top: "50%", transform: "translateY(-50%)" }} aria-hidden="true" />
            <span className="ei-hw-pass-eyebrow">Destination Reached</span>
            <div className="ei-hw-pass-city">Malaysia <MYFlag /></div>
            <p className="ei-hw-pass-sub">Your university journey starts here.</p>
            <span className="ei-hw-arrived"><StampSVG label="Arrived" sub="✓ Success" /></span>
            <DoodleSpot pos={{ right: "8%", bottom: "10%" }} width={54} d="0.4s"><Doodle.Loop /></DoodleSpot>
          </div>
          <div className="ei-hw-stub" data-reveal style={{ "--d": "0.12s" }}>
            <span className="ei-hw-notch" style={{ right: -18, top: "50%", transform: "translateY(-50%)", background: "#FBF6EC" }} aria-hidden="true" />
            <span className="ei-hw-stub-small">Everything on this page?</span>
            <span className="ei-hw-stub-big">100% FREE</span>
            <div className="ei-cta-actions">
              <a href="https://api.leadconnectorhq.com/widget/booking/dNgEYHHdDDzwv4Hgn3Dy" target="_blank" rel="noopener noreferrer" className="ei-btn-white">
                <Calendar size={16} /> Start Your Application <ArrowRight size={17} />
              </a>
              <a href="https://api.leadconnectorhq.com/widget/survey/oICk3R6Jw3DEls3KtKTv" target="_blank" rel="noopener noreferrer" className="ei-btn-dark">
                Get Free Guidance <ArrowRight size={17} />
              </a>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}



/* ------------------------------ Blogs Page ------------------------------- */

const BLOG_CATS = [
  { name: "Study Tips", Icon: GraduationCap, color: "#F05A28" },
  { name: "Scholarships", Icon: Trophy, color: "#B7791F" },
  { name: "Student Visa", Icon: FileText, color: "#2456A6" },
  { name: "Malaysia Life", Icon: HeartIcon, color: "#DB2777" },
  { name: "Universities", Icon: Building2, color: "#2F855A" },
  { name: "Career", Icon: Briefcase, color: "#7C3AED" },
  { name: "Success Stories", Icon: StarIcon, color: "#C2410C" },
];
const catColor = (name) => (BLOG_CATS.find((c) => c.name === name) || BLOG_CATS[0]).color;

// ── Google Sheets data source ──────────────────────────────────────────────
const SHEET_ID = "1pRKB-2eNui5Pf08P675aBkt_fLvee2by3Fp72O-qhYo";
const SHEET_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/gviz/tq?tqx=out:json`;

function formatGoogleDriveUrl(url) {
  if (!url) return '';
  const match = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
  if (match && match[1]) {
    return `https://lh3.googleusercontent.com/d/${match[1]}`;
  }
  return url;
}

/** Parse the Google Sheets gviz JSON response into article objects */
function parseSheetRows(raw) {
  try {
    const json = raw.match(/google\.visualization\.Query\.setResponse\((.+)\);?\s*$/s)?.[1];
    if (!json) return [];
    const data = JSON.parse(json);
    const cols = data?.table?.cols ?? [];
    const rows = data?.table?.rows ?? [];
    if (rows.length === 0) return [];

    let colIndices = {
      title: 0, cat: 1, read: 2, excerpt: 3, image: 4, url: 5, slug: 6, content: 7, date: 8, status: 9, featured: 10, author: 11
    };

    // Use gviz column labels if available
    cols.forEach((col, idx) => {
      const label = (col?.label || col?.id || '').toString().toLowerCase().trim();
      if (label.includes('title')) colIndices.title = idx;
      else if (label.includes('cat')) colIndices.cat = idx;
      else if (label.includes('read')) colIndices.read = idx;
      else if (label.includes('excerpt') || label.includes('desc')) colIndices.excerpt = idx;
      else if (label.includes('img') || label.includes('image')) colIndices.image = idx;
      else if ((label.includes('url') || label.includes('link') || label.includes('article')) && !label.includes('img') && !label.includes('image')) colIndices.url = idx;
      else if (label.includes('slug')) colIndices.slug = idx;
      else if (label.includes('content') || label.includes('body')) colIndices.content = idx;
      else if (label.includes('date')) colIndices.date = idx;
      else if (label.includes('status')) colIndices.status = idx;
      else if (label.includes('feat')) colIndices.featured = idx;
      else if (label.includes('author')) colIndices.author = idx;
    });

    return rows
      .map((r) => {
        const cell = (idx) => {
          const val = r.c?.[idx];
          if (!val) return '';
          return (val.f || val.v || '').toString().trim();
        };
        const featVal = cell(colIndices.featured).toLowerCase();
        let s = cell(colIndices.slug);
        let u = cell(colIndices.url);
        
        // If they provided a URL but no slug, and the URL doesn't look like an absolute URL, they might have put the slug in the URL column.
        if (!s && u && !u.startsWith('http')) {
          s = u;
          u = '';
        }
        
        return {
          title:    cell(colIndices.title),
          cat:      cell(colIndices.cat) || 'Study Tips',
          read:     cell(colIndices.read) || '5 min read',
          excerpt:  cell(colIndices.excerpt),
          image:    formatGoogleDriveUrl(cell(colIndices.image)),
          url:      u,
          slug:     s,
          content:  cell(colIndices.content),
          date:     cell(colIndices.date),
          status:   cell(colIndices.status) || 'published',
          featured: ['true', 'yes', '1', 'featured', 'y'].includes(featVal),
          author:   cell(colIndices.author),
        };
      })
      .filter((p) => p.title && p.status.toLowerCase() === 'published');
  } catch (e) {
    console.error('Sheet parse error:', e);
    return [];
  }
}


